from collections import deque
indeg = [0]*n
for v in range(n):
    for u in adj[v]: indeg[u] += 1
q = deque(i for i in range(n) if indeg[i] == 0)
order = []
while q:
    v = q.popleft(); order.append(v)
    for u in adj[v]:
        indeg[u] -= 1
        if indeg[u] == 0: q.append(u)
# len(order) < n means cycle existed

